-- CA_0144_la_trustee_area_boards_batch1.sql
-- LA-County TRUSTEE-AREA unified school boards, batch 1: Covina-Valley, Rowland, Duarte, South Pasadena.
--
-- WHAT THIS FIXES. Each of these districts elects its board BY TRUSTEE AREA, but the DB held all
-- five seats on ONE whole-district row (TIGER G5420), so every address in the district returned all
-- five members -- and the five held were STALE (none is on the district's current board page).
-- For each district this migration:
--   1. loads one polygon per trustee area (mtfcc X0002, the school sub-district layer the Part A
--      join already admits), dissolved from the LA County Registrar-Recorder precinct layer
--      (public.gis.lacounty.gov .../Political_Boundaries/MapServer/34, DST_USD/DIV_USD, read
--      2026-09-22) -- the geography the Registrar uses to put each "Trustee Area No. N" contest
--      on a ballot. USD codes: 21 Covina-Valley, 24 Rowland, 7 Duarte, 32 South Pasadena (decoded by
--      point-in-polygon against the TIGER unified polygons);
--   2. creates one SCHOOL sub-district per area and moves one existing 'Board Member' office onto
--      each (id order -- the pairing is arbitrary because every holder on them is stale);
--   3. closes each stale term the day before the verified successor's term starts
--      (how_ended 'unknown', end date NOT researched), clears that person's is_incumbent (is_active
--      untouched) -- the convention agreed 2026-09-22 with the parallel LA roster session (CA_0143);
--   4. seats the CURRENT member of each area, each confirmed on the district's own board page
--      (URL in politicians.data_source) and cross-checked against the Registrar's Nov 2022 / Nov 2024
--      candidate lists and results. Term start = December of the election year, precision 'month'
--      (Ed Code 5017 seats members at the December organizational meeting). New rows: party NULL;
--   5. seeds the Nov 3 2026 trustee-area contests on '2026 LA County General' from the Registrar's
--      certified candidate list (id=4348); incumbents linked to the member just seated. Uncontested
--      areas are included (decision 2026-09-22).
--
-- Torrance was planned for this batch but is deferred: its Trustee Area D is vacant (Betty Lieu
-- joined the Torrance City Council on 2026-07-14) and the vacancy date and Cat Bones's (TA B)
-- appointment date are not yet sourced, and the schema forbids inventing them.
--
-- IDEMPOTENT: every insert NOT EXISTS-guarded; the office move is guarded on the office still being
-- on the whole-district row; stale-term closing only touches open terms not held by the named member.
BEGIN;

CREATE TEMP TABLE _seat (parent_geo text, geo_id text, label text, ta text, ord int, full_name text, first_name text,
                         last_name text, url text, existing_pid uuid, term_start date, prec text, how text, src text,
                         pid uuid) ON COMMIT DROP;
