-- ─── pre-flight: each parent row holds exactly one office per area, each with ONE stale open term ─
DO $$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n FROM (
    SELECT s.parent_geo FROM _seat s GROUP BY s.parent_geo
    HAVING count(*) <> (SELECT count(*) FROM essentials.offices o JOIN essentials.districts pd ON pd.id = o.district_id
                         WHERE pd.district_type = 'SCHOOL' AND pd.mtfcc = 'G5420' AND pd.geo_id = s.parent_geo)
       AND NOT EXISTS (SELECT 1 FROM essentials.districts d WHERE d.geo_id = min(s.geo_id) AND d.district_type = 'SCHOOL')) x;
  IF n <> 0 THEN RAISE EXCEPTION 'pre-flight: % district(s) whose office count differs from its trustee-area count', n; END IF;
END $$;

